import Foundation

protocol DiscountPolicy {
    func apply(to price: Int) -> Int
}

struct FlatDiscount: DiscountPolicy {
    func apply(to price: Int) -> Int {
        return price - 10
    }
}

final class PriceCalculator {
    func calculate(price: Int, policy: DiscountPolicy) -> Int {
        return policy.apply(to: price)
    }
}

let calc = PriceCalculator()
let total = calc.calculate(price: 100, policy: FlatDiscount())
print("Total: \(total)")

import Foundation

protocol MessageSender {
    func send(text: String)
}

final class ConsoleSender: MessageSender {
    func send(text: String) {
        print("Logged: \(text)")
    }
}

final class AlertService {
    let sender: MessageSender
    init(sender: MessageSender) {
        self.sender = sender
    }
    func alert(msg: String) {
        sender.send(text: msg)
    }
}

let service = AlertService(sender: ConsoleSender())
service.alert(msg: "Disk full")

