import Foundation

struct UserValidator {
    static func isValid(name: String) -> Bool {
        return !name.isEmpty
    }
}

struct UserRepo {
    static func save(name: String) {
        if UserValidator.isValid(name: name) {
            print("Saved \(name)")
        } else {
            print("Invalid name")
        }
    }
}

UserRepo.save(name: "Morgan")

