import Foundation

protocol Readable {
    func read() -> String
}

protocol Writable {
    func write(text: String)
}

final class MemoryBuffer: Readable, Writable {
    private var buffer = ""

    func write(text: String) {
        buffer = text
    }

    func read() -> String {
        return buffer
    }
}

let mem = MemoryBuffer()
mem.write(text: "Hello SOLID")
print("Buffer: \(mem.read())")

import Foundation

protocol DataFetcher {
    func fetch() -> String
}

final class MockFetcher: DataFetcher {
    func fetch() -> String {
        return "Mock payload"
    }
}

final class ContentManager {
    private let fetcher: DataFetcher

    init(fetcher: DataFetcher) {
        self.fetcher = fetcher
    }

    func displayContent() -> String {
        return fetcher.fetch()
    }
}

let mgr = ContentManager(fetcher: MockFetcher())
print(mgr.displayContent())
